import { historyOpen } from './chat-view'
const SHORTCUT_SLOTS = 9
export function numberedKeys(items, collapsed = false) {
  return items.filter(item => historyOpen(item) !== null).slice(0, SHORTCUT_SLOTS)
}
export const inRail = (row) => row.item.kind === 'chat' || row.state === 'live'
